from math import isfinite
from models import Output, BRAKE_ACK_S


def verify_brake(state, vehicle, now):
    """Check brake availability and acknowledgement after the request deadline."""
    if not vehicle.brake_available:
        return False
    waiting = state.brake_requested_at
    return waiting is None or now - waiting < BRAKE_ACK_S or vehicle.brake_applied


def plan_speed(command, stopped):
    """A latched stop overrides every remote target, including a simultaneous reset."""
    return 0.0 if stopped or command.reset_stop else command.target_mps


def braking_required(target, vehicle):
    """Braking is required whenever current speed exceeds target."""
    return isfinite(vehicle.speed_mps) and vehicle.speed_mps > target


def select_brake(target, stopped, reasons, vehicle):
    """Local emergency trips outrank service braking; stopped vehicles are held."""
    slowing = braking_required(target, vehicle)
    if stopped and any(reason in reasons for reason in ('estop', 'collision_envelope', 'brake_fault')):
        return 'emergency'
    if stopped or slowing:
        return 'hold' if isfinite(vehicle.speed_mps) and vehicle.speed_mps <= 0.1 else 'service'
    return 'hold' if target == 0 else 'release'


def apply_interlocks(target, brake, vehicle):
    """Never request positive traction with commanded or reported braking."""
    traction = brake == 'release' and not vehicle.brake_applied and target > vehicle.speed_mps
    return Output(target, brake, bool(traction))

