"""Stop arbitration and explicit stationary reset."""


def evaluate_safety(command_ok, vehicle_ok, clearance_ok, brake_ok, vehicle):
    """Collect stop causes without allowing a remote request to mask a local trip."""
    checks = ((command_ok, 'command_invalid'), (vehicle_ok, 'vehicle_invalid'),
              (clearance_ok, 'collision_envelope'), (brake_ok, 'brake_fault'),
              (not vehicle.estop, 'estop'))
    return tuple(reason for healthy, reason in checks if not healthy)


def reset_stop(state, command, vehicle, reasons):
    """A fresh valid reset is effective only with all trips cleared at standstill."""
    if command.reset_stop and not reasons and vehicle.speed_mps <= 0.1:
        state.stop_latched = False
        state.stop_reasons = ()


def latch_stop(state, reasons):
    """Preserve stop and its original causes until a permitted explicit reset."""
    if reasons:
        state.stop_latched = True
        state.stop_reasons = tuple(dict.fromkeys(state.stop_reasons + reasons))
    return state.stop_latched

